import React, { useEffect, useState } from 'react'
import {Link} from "react-router-dom";
import './Reports.css'
import axios from "axios";


export default function Reports() {


    const [user, setUser] = useState(null);
    const localUser = JSON.parse(localStorage.getItem('user'))
    useEffect(() => {
        const fetchUser = async () => {
            try {
                const res = await axios.get('/api/user/' + localUser._id);
                setUser(res.data);
            } catch (error) {
                console.error('Error fetching user data:', error);
            }
        };
        fetchUser();
    }, [localUser._id]);




    return (
        <>
                <div className="ReportsButton">
                    {(user.role_id === '3' || user.role_id === '4') && (
                        <Link to='/ReportsHistory' className='linkReports'>Отчет по истории</Link>
                    )}
                    <br/>
                    <Link to='/ReportsNominations' className='linkReports'>Отчет по номинациям</Link>
            </div>
        </>
    )
}
